<?php
/**
 * SaaS Searchable Dropdown v2 (28 Nov 2026)
 * Safe, idempotent installer. Only updates two shared asset references + storefront references.
 * Run from the Laravel project root next to artisan: php saas_searchable_dropdown_fix_patch.php --dry-run / --apply.
 */
declare(strict_types=1);

$root = __DIR__;
$mode = $argv[1] ?? '--help';
$targets = [
    'resources/views/portals/partials/theme-styles.blade.php' => ['css'],
    'resources/views/portals/partials/ui-controls.blade.php' => ['js'],
    'resources/views/public/business/public/ecommerce/layout.blade.php' => ['css', 'js'],
];
$assets = [
    'public/assets/saas-searchable-select-v2.js' => base64_decode(
        ''
    ),
    'public/assets/saas-searchable-select-v2.css' => base64_decode(
        ''
    ),
];
$allowedPaths = array_merge(array_keys($targets), array_keys($assets));

function pathAt(string $root, string $relative): string {
    return $root.DIRECTORY_SEPARATOR.str_replace('/', DIRECTORY_SEPARATOR, $relative);
}
function writeOrFail(string $path, string $bytes): void {
    $dir = dirname($path);
    if (!is_dir($dir) && !mkdir($dir, 0775, true) && !is_dir($dir)) throw new RuntimeException("Cannot make directory: $dir");
    if (file_put_contents($path, $bytes, LOCK_EX) !== strlen($bytes)) throw new RuntimeException("Write failed: $path");
}
function updateReference(string $content, string $extension, string $file): string {
    $pattern = '~asset\(\s*\x27assets/saas-searchable-select\.'.$extension.'\x27\s*\)\s*\}\}\s*\?v=[0-9]+~';
    $replacement = "asset('assets/saas-searchable-select-v2.$extension') }}?v=20261128";
    $updated = preg_replace($pattern, $replacement, $content, 1, $number);
    if ($updated === null) throw new RuntimeException("Invalid search pattern in $file");
    if ($number === 1) return $updated;
    if (substr_count($content, "assets/saas-searchable-select-v2.$extension") === 1
        && strpos($content, "assets/saas-searchable-select.$extension") === false) return $content;
    throw new RuntimeException("Cannot safely identify the old searchable-select $extension include in $file. Nothing was changed.");
}
function readOrFail(string $file): string {
    if (!is_file($file) || !is_readable($file)) throw new RuntimeException("Missing/unreadable: $file");
    $content = file_get_contents($file);
    if ($content === false) throw new RuntimeException("Cannot read: $file");
    return $content;
}

try {
    if (!is_file(pathAt($root, 'artisan'))) throw new RuntimeException('Place this PHP patch beside the Laravel artisan file.');
    if (str_starts_with($mode, '--rollback=')) {
        $name = basename(substr($mode, 11));
        if (!preg_match('/^searchable_select_v2_[0-9]{8}_[0-9]{6}_[a-f0-9]{6}$/', $name)) throw new RuntimeException('Invalid backup identifier.');
        $folder = pathAt($root, '.saas_backups/'.$name);
        $data = json_decode(readOrFail($folder.'/manifest.json'), true, 512, JSON_THROW_ON_ERROR);
        if (($data['patch'] ?? '') !== 'saas-searchable-v2') throw new RuntimeException('This backup is not from this patch.');
        foreach ($data['files'] as $file) {
            $relative = $file['path'];
            if (!in_array($relative, $allowedPaths, true)) throw new RuntimeException('Unexpected file in manifest.');
            $current = readOrFail(pathAt($root, $relative));
            if (hash('sha256', $current) !== $file['sha256_after']) throw new RuntimeException("Rollback refused: $relative changed after patch installation.");
            if ($file['operation'] === 'modified') {
                $old = readOrFail($folder.'/original/'.$relative);
                if (hash('sha256', $old) !== $file['sha256_before']) throw new RuntimeException("Backup mismatch: $relative");
            }
        }
        foreach (array_reverse($data['files']) as $file) {
            $target = pathAt($root, $file['path']);
            if ($file['operation'] === 'created') { if (!unlink($target)) throw new RuntimeException("Cannot remove: $target"); }
            else writeOrFail($target, readOrFail($folder.'/original/'.$file['path']));
            echo "RESTORED  {$file['path']}\n";
        }
        echo "ROLLBACK OK; backup retained at .saas_backups/$name\n";
        exit(0);
    }
    if (!in_array($mode, ['--dry-run', '--apply'], true)) {
        echo "Usage:\n  php saas_searchable_dropdown_fix_patch.php --dry-run\n  php saas_searchable_dropdown_fix_patch.php --apply\n  php saas_searchable_dropdown_fix_patch.php --rollback=BACKUP_ID\n";
        exit($mode === '--help' ? 0 : 1);
    }
    $changes = [];
    foreach ($targets as $relative => $extensions) {
        $original = readOrFail(pathAt($root, $relative));
        $updated = $original;
        foreach ($extensions as $ext) $updated = updateReference($updated, $ext, $relative);
        if ($updated !== $original) $changes[$relative] = ['op'=>'modified', 'before'=>$original, 'after'=>$updated];
    }
    foreach ($assets as $relative => $bytes) {
        $file = pathAt($root, $relative);
        if (!is_file($file)) $changes[$relative] = ['op'=>'created', 'before'=>'', 'after'=>$bytes];
        elseif (readOrFail($file) !== $bytes) throw new RuntimeException("An existing $relative differs. No assets overwritten; review and merge manually.");
    }
    if (!$changes) { echo "ALREADY APPLIED — no changes needed.\n"; exit(0); }
    foreach ($changes as $relative => $change) echo ($mode === '--dry-run' ? 'WOULD ' : '').strtoupper($change['op'])."  $relative\n";
    if ($mode === '--dry-run') { echo "DRY RUN OK — ".count($changes)." file(s), no database change.\n"; exit(0); }
    $name = 'searchable_select_v2_'.date('Ymd_His').'_'.bin2hex(random_bytes(3));
    $backup = pathAt($root, '.saas_backups/'.$name);
    $manifest = ['patch'=>'saas-searchable-v2','created_at'=>date(DATE_ATOM),'files'=>[]];
    foreach ($changes as $relative => $change) {
        if ($change['op'] === 'modified') writeOrFail($backup.'/original/'.$relative, $change['before']);
        $manifest['files'][] = ['path'=>$relative, 'operation'=>$change['op'], 'sha256_before'=>hash('sha256', $change['before']), 'sha256_after'=>hash('sha256', $change['after'])];
    }
    writeOrFail($backup.'/manifest.json', json_encode($manifest, JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));
    $applied = [];
    try {
        foreach ($changes as $relative => $change) {
            $file = pathAt($root, $relative);
            if ($change['op'] === 'modified' && readOrFail($file) !== $change['before']) throw new RuntimeException("File changed during installation: $relative");
            if ($change['op'] === 'created' && file_exists($file)) throw new RuntimeException("File appeared during installation: $relative");
            writeOrFail($file, $change['after']);
            $applied[] = $relative;
            if (hash_file('sha256', $file) !== hash('sha256', $change['after'])) throw new RuntimeException("Verification failed: $relative");
        }
    } catch (Throwable $error) {
        foreach (array_reverse($applied) as $relative) {
            $change = $changes[$relative];
            if ($change['op'] === 'created') { if (is_file(pathAt($root,$relative))) unlink(pathAt($root,$relative)); }
            else writeOrFail(pathAt($root, $relative), $change['before']);
        }
        throw new RuntimeException('Installation stopped; applied files restored. '.$error->getMessage(), 0, $error);
    }
    echo "APPLY OK — ".count($applied)." file(s).\nBACKUP: .saas_backups/$name\nROLLBACK: php saas_searchable_dropdown_fix_patch.php --rollback=$name\n";
} catch (Throwable $e) {
    fwrite(STDERR, "ERROR: {$e->getMessage()}\n");
    exit(1);
}
